const styleId = 'missions-mobiglass-css';
const missionApi = '/api/' + 'missions';
const state = { groups: [], groupId: '', missions: [], statusFilter: 'all', search: '', loadingGroups: false, loadingMissions: false, groupError: false, missionError: false, accessChanged: false, selectedMissionId: null, selectedMission: null, loadingDetail: false, detailError: false, detailNotFound: false, detailAccessChanged: false, focusTaskId: null, taskTargetMissing: false, me: null, dialog: null, mutationPending: false, taskActions: {}, copyStatus: {} };
let groupRequestGeneration = 0;
let missionListRequestGeneration = 0;
let missionDetailRequestGeneration = 0;
let mountedRoot = null;
let meRequest = null;
let dialogReturnFocus = '';
let dialogActiveField = '';

const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const isCurrentView = () => location.hash === '#missions';
const selectedGroup = () => state.groups.find(group => group.id === state.groupId);
const isGroupRequestLive = generation => isCurrentView() && generation === groupRequestGeneration;
const isMissionListRequestLive = (generation, groupId) => isCurrentView() && generation === missionListRequestGeneration && state.groupId === groupId;
const isMissionDetailRequestLive = (generation, missionId) => isCurrentView() && generation === missionDetailRequestGeneration && state.selectedMissionId === missionId;
const uuid = value => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ''));
const missionLocatorFromUrl = () => { const params = new URLSearchParams(location.search), missionId = params.get('mission_id'); return missionId ? { groupId: params.get('group_id') || '', missionId, taskId: params.get('task_id') || '' } : null; };
const currentTaskTarget = missionId => { const locator = missionLocatorFromUrl(); return locator?.missionId === missionId && locator.taskId ? locator.taskId : state.focusTaskId || ''; };
const setMissionLocation = ({ groupId, missionId, taskId, mode = 'push' }) => { const url = new URL(location.href); url.searchParams.set('group_id', groupId); url.searchParams.set('mission_id', missionId); if (taskId) url.searchParams.set('task_id', taskId); else url.searchParams.delete('task_id'); url.searchParams.delete('order_id'); url.hash = 'missions'; history[mode === 'replace' ? 'replaceState' : 'pushState'](null, '', url); };
const buildMissionDeepLink = ({ groupId, missionId, taskId = '' }) => { const url = new URL(location.href); url.searchParams.set('group_id', groupId); url.searchParams.set('mission_id', missionId); if (taskId) url.searchParams.set('task_id', taskId); else url.searchParams.delete('task_id'); url.searchParams.delete('order_id'); url.hash = 'missions'; return url.toString(); };
const clearMissionLocation = ({ mode = 'replace' } = {}) => { const url = new URL(location.href); for (const key of ['group_id', 'mission_id', 'task_id']) url.searchParams.delete(key); history[mode === 'push' ? 'pushState' : 'replaceState'](null, '', url); };
const clampPercent = value => Math.max(0, Math.min(100, Number.isFinite(Number(value)) ? Number(value) : 0));
const timestamp = value => { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'UNKNOWN' : date.toLocaleString(); };
const readableStatus = value => ({ open: 'OPEN', in_progress: 'IN PROGRESS', completed: 'COMPLETED', cancelled: 'CANCELLED' }[value] || String(value || 'UNKNOWN').replaceAll('_', ' ').toUpperCase());
const formatQuantity = value => { const numeric = Number(value); return Number.isFinite(numeric) ? String(numeric) : ''; };
const groupFor = mission => state.groups.find(group => group.id === mission?.group_id);
const memberName = (mission, userId) => groupFor(mission)?.members?.find(member => member.user_id === userId)?.name || '';
const taskAssignee = task => task['assigned' + '_to'];
const taskAssigneeLabel = (mission, task) => { const userId = taskAssignee(task); return !userId ? 'UNASSIGNED' : memberName(mission, userId) || 'FORMER MEMBER'; };
const missionCreatorLabel = mission => !mission?.created_by ? 'FORMER USER' : memberName(mission, mission.created_by) || 'FORMER MEMBER';
const canManageMission = mission => Boolean(state.me?.is_admin || state.me?.id === mission?.created_by || groupFor(mission)?.role === 'owner');
const canActOnTask = (mission, task) => Boolean(canManageMission(mission) || state.me?.id && taskAssignee(task) === state.me.id);
const actionKey = (taskId, kind) => `${taskId}:${kind}`;
const taskActionFor = (taskId, kind) => state.taskActions[actionKey(taskId, kind)] || {};
const isTaskPending = taskId => Object.entries(state.taskActions).some(([key, action]) => key.startsWith(`${taskId}:`) && action.pending);
const taskActionMessage = task => Object.entries(state.taskActions).filter(([key]) => key.startsWith(`${task.id}:`)).map(([, action]) => `${action.error ? `<p role="alert">${esc(action.error)}</p>` : ''}${action.success ? `<p role="status">${esc(action.success)}</p>` : ''}`).join('');

