const shell = content => `<section class="missions-shell"><div class="missions-brand"><img class="missions-logo" src="/assets/apps/missions.png" alt="Missions"><div class="missions-brand-copy"><div class="eyebrow">MOBIGLASS APPLICATION</div><h1>MISSIONS</h1></div></div>${content}</section>`;
const statePanel = (title, text, action = '') => `<div class="missions-state" ${title.includes('LOADING') ? 'role="status"' : title.includes('UNAVAILABLE') || title.includes('CHANGED') || title === 'MISSION NOT FOUND' ? 'role="alert"' : ''}><div>${title.includes('LOADING') ? '<div class="missions-loading-mark" aria-hidden="true"></div>' : ''}<strong>${title}</strong><p>${text}</p>${action}</div></div>`;
const loadingGroups = () => statePanel('LOADING GROUP CONTEXT...', 'Validating VerseLink group context.');
const loadingMissions = () => statePanel('LOADING MISSIONS...', 'Retrieving the selected group mission overview.');
const noGroups = () => statePanel('NO GROUPS AVAILABLE', 'Missions belong to VerseLink groups. Create or join a group before planning a mission.', '<button type="button" data-missions-groups>OPEN GROUP MANAGEMENT</button>');
const groupUnavailable = () => statePanel('GROUP CONTEXT UNAVAILABLE', 'Unable to load VerseLink group context.', '<button type="button" data-missions-retry-groups>RETRY GROUPS</button>');
const missionUnavailable = () => statePanel('MISSION DATA UNAVAILABLE', 'Unable to load missions for the selected group.', '<button type="button" data-missions-retry-missions>RETRY</button>');
const accessChanged = () => statePanel('GROUP ACCESS CHANGED', 'Your group access changed. Refresh group context before continuing.', '<button type="button" data-missions-refresh-groups>REFRESH GROUPS</button>');

const visibleMissions = () => { const search = state.search.trim().toLowerCase(); return state.missions.filter(mission => { const statusMatches = state.statusFilter === 'all' || (state.statusFilter === 'active' ? ['open', 'in_progress'].includes(mission.status) : mission.status === state.statusFilter); return statusMatches && (!search || String(mission.title ?? '').toLowerCase().includes(search)); }); };
const missionCard = mission => { const percent = clampPercent(mission.progress_percent), historical = ['completed', 'cancelled'].includes(mission.status); return `<article class="missions-card ${historical ? 'historical' : 'active'}"><div class="missions-label">${esc(selectedGroup()?.name || 'SELECTED GROUP')} · ${readableStatus(mission.status)}</div><h2>${esc(mission.title || 'UNTITLED MISSION')}</h2>${mission.description ? `<p class="missions-summary">${esc(String(mission.description).slice(0, 180))}</p>` : ''}<div class="missions-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-label="Mission progress"><span style="width:${percent}%"></span></div><div class="missions-meta">${percent}% · ${Number(mission.active_task_count) || 0} ACTIVE TASKS</div><div class="missions-meta">CREATED ${timestamp(mission.created_at)} · UPDATED ${timestamp(mission.updated_at)}${mission.status === 'completed' ? ` · COMPLETED ${timestamp(mission.completed_at)}` : ''}</div><button type="button" data-mission-open="${esc(mission.id)}">OPEN MISSION</button></article>`; };
const missionResults = () => { const missions = visibleMissions(); if (!state.missions.length) return statePanel('NO MISSIONS', 'No missions are available for this group.'); if (!missions.length) return statePanel('NO MATCHING MISSIONS', 'No missions match the current filters.', '<button type="button" data-missions-clear>CLEAR FILTERS</button>'); return `<div class="missions-list">${missions.map(missionCard).join('')}</div>`; };
const overview = () => { const filters = [['all', 'ALL'], ['active', 'ACTIVE'], ['open', 'OPEN'], ['in_progress', 'IN PROGRESS'], ['completed', 'COMPLETED'], ['cancelled', 'CANCELLED']]; return `<div class="missions-toolbar"><div class="missions-controls"><select data-missions-group aria-label="Mission group">${state.groups.map(group => `<option value="${esc(group.id)}" ${group.id === state.groupId ? 'selected' : ''}>${esc(group.name)}</option>`).join('')}</select><button type="button" data-missions-refresh>REFRESH</button><button type="button" data-mission-create>＋ CREATE MISSION</button></div><div class="missions-filters" aria-label="Mission status filters">${filters.map(([value, label]) => `<button type="button" data-missions-filter="${value}" aria-pressed="${state.statusFilter === value}">${label}</button>`).join('')}</div><input class="missions-search" data-missions-search type="search" value="${esc(state.search)}" placeholder="SEARCH MISSION TITLES" aria-label="Search mission titles"></div><div data-missions-results>${missionResults()}</div>`; };
const renderMissionResults = () => { const results = mountedRoot?.querySelector('[data-missions-results]'); if (!results || !isCurrentView()) return; results.innerHTML = missionResults(); mountedRoot.querySelectorAll('[data-missions-filter]').forEach(button => { button.setAttribute('aria-pressed', String(button.dataset.missionsFilter === state.statusFilter)); }); bindResults(results); };

const taskCard = (mission, task) => { const percent = clampPercent(task.progress_percent), item = task.type === 'item', assignee = taskAssigneeLabel(mission, task), unit = task.unit ? ` ${esc(task.unit)}` : '', manage = canManageMission(mission), act = canActOnTask(mission, task), pending = isTaskPending(task.id), focused = state.focusTaskId === task.id, members = groupFor(mission)?.members || [], former = taskAssignee(task) && !memberName(mission, taskAssignee(task)), assignmentAction = taskActionFor(task.id, 'assignment'), assignmentDraft = assignmentAction.draft, assignmentValue = assignmentDraft === undefined ? (former ? '__former__' : taskAssignee(task) || '') : assignmentDraft, assignmentBlocked = former && assignmentDraft === undefined, contributionAction = taskActionFor(task.id, 'contribution'), historyRows = task['contrib' + 'utions'] || []; const value = (label, content) => `<div><span class="missions-label">${label}</span><strong>${content}</strong></div>`; const assignment = manage ? `<form data-task-assignment="${esc(task.id)}"><label>ASSIGNMENT<select name="assignee" ${pending ? 'disabled' : ''}><option value="" ${assignmentValue === '' ? 'selected' : ''}>UNASSIGNED</option>${former ? `<option value="__former__" ${assignmentValue === '__former__' ? 'selected' : ''} disabled>FORMER MEMBER</option>` : ''}${members.map(member => `<option value="${esc(member.user_id)}" ${assignmentValue === member.user_id ? 'selected' : ''}>${esc(member.name)}</option>`).join('')}</select></label><button type="submit" ${pending || assignmentBlocked ? 'disabled' : ''}>${pending ? 'UPDATING...' : 'APPLY ASSIGNMENT'}</button></form>` : ''; const checklist = !item && task.status !== 'cancelled' && act ? `<button type="button" data-checklist-action="${esc(task.id)}" data-status="${task.status === 'completed' ? 'open' : 'completed'}" ${pending ? 'disabled' : ''}>${pending ? 'UPDATING...' : task.status === 'completed' ? 'REOPEN' : 'MARK COMPLETE'}</button>` : ''; const remaining = Number(task.remaining_quantity), contribution = item && task.status !== 'cancelled' && remaining > 0 && act ? `<form data-task-contribution="${esc(task.id)}"><label>CONTRIBUTION<input name="quantity" type="number" step="any" min="0" value="${esc(contributionAction.draft ?? '')}" ${pending ? 'disabled' : ''}></label><button type="submit" ${pending ? 'disabled' : ''}>${pending ? 'ADDING...' : 'ADD CONTRIBUTION'}</button></form>` : item && remaining <= 0 ? '<div class="missions-label">TARGET REACHED</div>' : ''; const history = item && historyRows.length ? `<div><div class="missions-label">CONTRIBUTIONS</div>${historyRows.map(entry => `<div class="missions-meta">${esc(entry.contributor_name || 'FORMER USER')} · ${formatQuantity(entry.quantity)}${unit} · ${timestamp(entry.created_at)}</div>`).join('')}</div>` : ''; return `<article class="mission-task ${item ? 'item' : 'checklist'} ${task.status === 'cancelled' ? 'cancelled' : ''}${focused ? ' mission-task-focus' : ''}" data-mission-task-id="${esc(task.id)}" ${focused ? 'tabindex="-1"' : ''}><div class="mission-type">${item ? 'ITEM' : task.type === 'checklist' ? 'CHECKLIST' : 'TASK'} · ${readableStatus(task.status)}</div><h3>${esc(task.title || 'UNTITLED TASK')}</h3>${task.description ? `<p class="missions-summary">${esc(task.description)}</p>` : ''}<div class="mission-task-grid">${value('ASSIGNED TO', esc(assignee))}${value('STATUS', readableStatus(task.status))}${item ? `${value('TARGET', `${formatQuantity(task.target_quantity)}${unit}`)}${value('CURRENT', `${formatQuantity(task.current_quantity)}${unit}`)}${value('REMAINING', `${formatQuantity(task.remaining_quantity)}${unit}`)}` : value('COMPLETION', readableStatus(task.status))}</div><div class="missions-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-label="Task progress"><span style="width:${percent}%"></span></div><div class="missions-meta">${percent}% PROGRESS</div><div class="mission-task-actions">${assignment}${checklist}${contribution}${taskActionMessage(task)}</div>${history}</article>`; };
const detailView = mission => { const percent = clampPercent(mission.progress_percent), group = groupFor(mission), creator = missionCreatorLabel(mission), manage = canManageMission(mission); const value = (label, content) => `<div><span class="missions-label">${label}</span><strong>${content}</strong></div>`; return `<section class="mission-detail"><div class="mission-detail-head"><div><div class="missions-label">${esc(group?.name || 'KNOWN GROUP')} · ${readableStatus(mission.status)}</div><h2>${esc(mission.title || 'UNTITLED MISSION')}</h2>${mission.description ? `<p class="missions-summary">${esc(mission.description)}</p>` : ''}</div><div class="mission-detail-actions"><button type="button" data-mission-back>BACK TO MISSIONS</button><button type="button" data-mission-refresh>REFRESH</button>${manage ? '<button type="button" data-mission-edit>EDIT MISSION</button>' : ''}</div></div>${state.taskTargetMissing ? '<p role="status">TASK NO LONGER AVAILABLE</p>' : ''}<div class="missions-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-label="Mission progress"><span style="width:${percent}%"></span></div><div class="mission-detail-summary">${value('STATUS', readableStatus(mission.status))}${value('PROGRESS', `${percent}%`)}${value('GROUP', esc(group?.name || 'UNKNOWN'))}${value('ACTIVE TASKS', String(Number(mission.active_task_count) || 0))}${value('CREATED', timestamp(mission.created_at))}${value('UPDATED', timestamp(mission.updated_at))}${mission.completed_at ? value('COMPLETED', timestamp(mission.completed_at)) : ''}${value('CREATOR', esc(creator))}</div><section><div class="missions-label">TASKS ${manage ? '<button type="button" data-task-create>＋ ADD TASK</button>' : ''}</div><div class="mission-tasks">${Array.isArray(mission.tasks) && mission.tasks.length ? mission.tasks.map(task => taskCard(mission, task)).join('') : statePanel('NO TASKS', 'No direct tasks are available for this mission.')}</div></section></section>`; };
